# STORY-001 — Owner account
#
# Entry point: the routed LiveViews/controllers generated by
# `mix phx.gen.auth Accounts User users --live`, plus `/dashboard`.
# Email goes through Swoosh.Adapters.Test, which messages the test process.
defmodule FirmosWeb.Features.OwnerAccountTest do
  @moduledoc "Feature: an owner signs up and logs in with their email"
  use FirmosWeb.ConnCase, async: true

  import Phoenix.LiveViewTest

  alias Firmos.Accounts

  defp unique_email, do: "owner-#{System.unique_integer([:positive])}@example.com"

  defp register(conn, email) do
    {:ok, view, _html} = live(conn, ~p"/users/register")

    result =
      view
      |> form("#registration_form", user: %{email: email})
      |> render_submit()

    assert_received {:email, sent_email}
    %{result: result, sent_email: sent_email}
  end

  defp token_from(%{text_body: body}) do
    [_, token] = Regex.run(~r{/users/log-in/([\w-]+)}, body)
    token
  end

  # ---------------------------------------------------------------------
  # HAPPY PATH
  # ---------------------------------------------------------------------

  describe "Scenario: AC1 — a visitor signs up with a valid email" do
    setup %{conn: conn} do
      email = unique_email()
      Map.put(register(conn, email), :email, email)
    end

    test "creates an account", %{email: email} do
      assert %{email: ^email} = Accounts.get_user_by_email(email)
    end

    test "emails the login link to the visitor", %{sent_email: sent_email, email: email} do
      assert [{_, ^email}] = sent_email.to
    end

    test "the email carries a magic login link", %{sent_email: sent_email} do
      assert sent_email.text_body =~ ~r{/users/log-in/[\w-]+}
    end

    test "sends the visitor to the log-in page", %{result: result} do
      assert {:error, {:live_redirect, %{to: "/users/log-in"}}} = result
    end
  end

  describe "Scenario: AC2 — a registered owner opens a valid magic link" do
    setup %{conn: conn} do
      %{sent_email: sent_email} = register(conn, unique_email())
      token = token_from(sent_email)

      {:ok, view, _html} = live(build_conn(), ~p"/users/log-in/#{token}")
      form = form(view, "#confirmation_form", %{"user" => %{"token" => token}})
      render_submit(form)
      conn = follow_trigger_action(form, build_conn())

      %{conn: conn}
    end

    test "redirects to the dashboard", %{conn: conn} do
      assert redirected_to(conn) == ~p"/dashboard"
    end

    test "signs the owner in", %{conn: conn} do
      assert get_session(conn, :user_token)
    end
  end

  describe "Scenario: AC2 — a signed-in owner views the dashboard" do
    setup %{conn: conn} do
      email = unique_email()
      %{sent_email: sent_email} = register(conn, email)
      token = token_from(sent_email)

      {:ok, view, _html} = live(build_conn(), ~p"/users/log-in/#{token}")
      form = form(view, "#confirmation_form", %{"user" => %{"token" => token}})
      render_submit(form)
      conn = follow_trigger_action(form, build_conn())

      {:ok, dashboard, _html} = live(recycle(conn), ~p"/dashboard")
      %{dashboard: dashboard, email: email}
    end

    test "renders the dashboard", %{dashboard: dashboard} do
      assert has_element?(dashboard, "#dashboard")
    end

    test "greets the owner by email", %{dashboard: dashboard, email: email} do
      assert has_element?(dashboard, "#dashboard", email)
    end
  end

  # ---------------------------------------------------------------------
  # SAD PATH
  # ---------------------------------------------------------------------

  describe "Scenario: AC3 — rejecting a malformed email on sign-up" do
    setup %{conn: conn} do
      {:ok, view, _html} = live(conn, ~p"/users/register")

      view
      |> form("#registration_form", user: %{email: "not-an-email"})
      |> render_submit()

      %{view: view}
    end

    test "shows an email format error on the form", %{view: view} do
      assert has_element?(view, "#registration_form p", "must have the @ sign and no spaces")
    end

    test "does not create an account" do
      refute Accounts.get_user_by_email("not-an-email")
    end

    test "does not send an email" do
      refute_received {:email, _}
    end
  end

  describe "Scenario: AC4 — rejecting an anonymous visit to the dashboard" do
    setup %{conn: conn} do
      %{conn: get(conn, ~p"/dashboard")}
    end

    test "redirects to the log-in page", %{conn: conn} do
      assert redirected_to(conn) == ~p"/users/log-in"
    end
  end
end
